const BUDGET_RANGES = {
  ate80: [0, 80], de80a150: [80, 150], de150a300: [150, 300], acima300: [300, 700],
};

const OCCASION_VOCACAO_WEIGHT = {
  cotidiano: 0.4, festa: 0.4, romantico: 0.8, negocios: 1.3, celebracao: 1.4,
};

/* ---------- Motor de scoring ---------- */
function scoreWine(wine, profile, session) {
  // Vivência: proximidade sensorial
  const diffs = ["body", "acid", "tannin", "fruit", "oak"].map((k) => Math.abs((profile[k] ?? 5) - wine.style[k]));
  const meanDiff = diffs.reduce((a, b) => a + b, 0) / diffs.length;
  let vivenciaScore = Math.max(0, 10 - meanDiff);
  // pequeno empurrão (não trava) quando o tipo do vinho é o favorito declarado
  if (profile.favoriteType && wine.tipo === profile.favoriteType) {
    vivenciaScore = Math.min(10, vivenciaScore + 0.6);
  }

  // Valor: faixa de preço que o próprio usuário definiu + papel esperado.
  // Catálogo real ainda não tem preço (aguardando exportação da CompreVinho) —
  // nesse caso o Valor fica neutro, sem inventar número, só considerando o papel.
  let valorScore;
  let valorPendente = wine.price == null;
  if (valorPendente) {
    valorScore = wine.role === session.role ? 7 : 5.5;
  } else {
    const [min, max] = BUDGET_RANGES[session.budget] || [70, 220];
    if (wine.price >= min && wine.price <= max) valorScore = 10;
    else {
      const dist = wine.price < min ? min - wine.price : wine.price - max;
      valorScore = Math.max(0, 10 - dist / 18);
    }
    if (wine.role === session.role) valorScore = Math.min(10, valorScore + 1);
    else valorScore = Math.max(0, valorScore - 1.5);
  }

  // Vínculo: comida + energia do ambiente
  const foodTarget = { body: session.food, tannin: session.food * 0.7, acid: 10 - session.food * 0.4 };
  const foodDiff = (Math.abs(foodTarget.body - wine.style.body) + Math.abs(foodTarget.tannin - wine.style.tannin) + Math.abs(foodTarget.acid - wine.style.acid)) / 3;
  let vinculoScore = Math.max(0, 10 - foodDiff);
  if (session.energy === "formal" || session.energy === "dinamico") vinculoScore -= wine.style.oak * 0.15;
  if (session.energy === "festivo") vinculoScore += (10 - wine.style.tannin) * 0.1 + wine.style.acid * 0.05;
  if (session.energy === "intimista") vinculoScore += (10 - wine.style.oak) * 0.05;
  vinculoScore = Math.max(0, Math.min(10, vinculoScore));

  // Vocação: regra de backend — nunca é pergunta direta ao usuário.
  // 1) tipicidade: o quanto esta garrafa específica expressa o DNA da região
  const region = wine.regionData;
  const typicityDiffs = ["body", "acid", "tannin", "fruit", "oak"].map((k) => Math.abs(region.typicalStyle[k] - wine.style[k]));
  const typicityFit = Math.max(0, 10 - typicityDiffs.reduce((a, b) => a + b, 0) / typicityDiffs.length);
  // 2) autoridade histórica da região (consistência comprovada ao longo do tempo)
  let vocacaoScore = region.baseStrength * 0.6 + typicityFit * 0.4;
  // 3) bônus de exploração: regiões emergentes ganham peso extra para perfis "explorador"
  const risk = profile.risk ?? 5; // 0 clássico … 10 explorador
  if (region.status === "emergente") {
    vocacaoScore += (risk - 5) * 0.3; // explorador (risk alto) empurra pra cima; clássico empurra pra baixo
  }
  vocacaoScore = Math.max(0, Math.min(10, vocacaoScore));
  // 4) peso final do pilar varia conforme o risco da ocasião (celebração/negócios pedem mais segurança)
  const vocacaoWeight = OCCASION_VOCACAO_WEIGHT[session.occasion] ?? 1;

  const total = vivenciaScore * 0.38 + valorScore * 0.24 + vinculoScore * 0.24 + vocacaoScore * 0.14 * vocacaoWeight;

  return { total, vivenciaScore, valorScore, vinculoScore, vocacaoScore, typicityFit, valorPendente };
}

function buildRationale(wine, scores, session) {
  const parts = [];
  if (scores.vivenciaScore >= 7) parts.push("a textura e o perfil de fruta conversam diretamente com o que você já validou como prazer");
  else if (scores.vivenciaScore >= 4.5) parts.push("o perfil sensorial chega perto do que você costuma preferir, com uma pequena variação");
  else parts.push("é um convite a sair um pouco da sua zona de conforto sensorial, com risco controlado");

  if (scores.valorPendente) {
    parts.push("o preço deste vinho ainda não está integrado ao app — o papel dele (protagonista/coadjuvante) já foi considerado, e a comparação com sua faixa de investimento entra assim que os dados de preço chegarem");
  } else {
    const [bmin, bmax] = BUDGET_RANGES[session.budget] || [];
    if (scores.valorScore >= 8) parts.push(`o preço (R$ ${wine.price}) está dentro da faixa de R$ ${bmin} a R$ ${bmax} que você definiu`);
    else parts.push(`o preço (R$ ${wine.price}) foge um pouco da faixa de R$ ${bmin} a R$ ${bmax} que você definiu, mas ainda se justifica pelo papel do vinho`);
  }

  if (scores.vinculoScore >= 7) parts.push("a estrutura dialoga bem com a comida e a energia do encontro");
  else parts.push("pode exigir um pequeno ajuste de expectativa frente ao clima do encontro");

  const region = wine.regionData;
  if (region.status === "classica" && scores.typicityFit >= 7) {
    parts.push(`a Vocação de ${wine.region} é um porto seguro — essa garrafa expressa quase à risca o que a região sabe entregar (${region.note})`);
  } else if (region.status === "emergente") {
    parts.push(`a Vocação de ${wine.region} ainda está em formação (${region.note}), o que é ótimo se você topa explorar fora do óbvio`);
  } else {
    parts.push(`a Vocação de ${wine.region} garante um piso de consistência, ainda que esta garrafa se desvie um pouco do estilo mais típico`);
  }

  return `Aqui, ${parts[0]}; ${parts[1]}; ${parts[2]}. Além disso, ${parts[3]}.`;
}

