/* ---------- Copiar nome do rótulo (pra colar na busca do CompreVinho) ----------
   Tenta a API moderna de clipboard primeiro; se ela existir mas falhar (comum
   em navegadores/ambientes com permissão restrita), cai pro método antigo
   (execCommand) em vez de simplesmente desistir. */
function copiarViaFallback(texto) {
  return new Promise((resolve, reject) => {
    try {
      const ta = document.createElement("textarea");
      ta.value = texto;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.focus();
      ta.select();
      const ok = document.execCommand("copy");
      document.body.removeChild(ta);
      if (ok) resolve(); else reject(new Error("execCommand retornou falso"));
    } catch (e) {
      reject(e);
    }
  });
}

function copiarTexto(texto) {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    return navigator.clipboard.writeText(texto).catch(() => copiarViaFallback(texto));
  }
  return copiarViaFallback(texto);
}

